	sections = {
		{
			title = "Summary",
			text = [=[The Druids of the Fang are the corrupted followers of {link:naralex}Naralex{/link}. They came to the {link:wailing-caverns}Wailing Caverns{/link} as an order of noble druids, meaning to heal the {link:the-barrens}Barrens{/link}. When their master's dream became a nightmare, most of them fell with him. Now they wear scaled faces and serpent shapes, and they seek to remake the land in the image of their own twisted dreams.]=],
		},
		{
			title = "The Order",
			text = [=[Four leaders command them, the Fanglords: {link:lady-anacondra}Lady Anacondra{/link}, {link:lord-cobrahn}Lord Cobrahn{/link}, {link:lord-pythas}Lord Pythas{/link} and their chief, {link:lord-serpentis}Lord Serpentis{/link}. Each holds a gem of the dream. Beneath them, druids of the Fang keep deviate serpents and raptors as their beasts, and some walk the plains above. One of them, Boahn, has been seen near the caverns' hill. The few disciples who kept their minds, among them Nalpak, Ebru and the Disciple who waits within, now work against their fallen brothers.]=],
		},
		{
			title = "What the Druids Saw",
			text = [=[{link:hamuul-runetotem}Hamuul Runetotem{/link} entered the dreaming to learn what was poisoning the {link:the-barrens}Barrens{/link}. He saw a cult of druids whose goals had once been noble and who had lost their way, serving the taint that seeped through the land. He was old and could not stay long. {link:nara-wildmane}Nara Wildmane{/link} remained, and saw their faces. She says they haunt her still.]=],
		},
	},
})
